import copy
import json
import math
import os
import subprocess
import sys

TRUSTED = {
    "fixed-v1": {
        "case1": {"left": 3, "right": 5, "total": 8, "critical": False},
        "case2": {"left": 12, "right": 4, "total": 16, "critical": True},
    },
    "changed-v1": {
        "learner-case-1": {"left": 14, "right": 9, "total": 23, "critical": True},
    },
}
ROLES = {"planner", "executor", "reviewer", "researcher"}
METRICS = {"tokens", "latencyMilliseconds", "costUnits", "retries", "toolCalls"}
POINTERS = [
    "https://openai.github.io/openai-agents-js/guides/multi-agent/",
    "https://adk.dev/workflows/",
    "https://code.claude.com/docs/en/sub-agents",
]
USAGE_SCOPE = "fixture aggregate for complete route; executorResult.toolCallCount is an executor-only subset"


def die(message):
    print("FAIL: " + message)
    raise SystemExit(1)


def finite_number(value):
    return (not isinstance(value, bool)
            and isinstance(value, (int, float))
            and math.isfinite(value))


def usage(tokens, latency, cost, retries, tools):
    return {
        "tokens": tokens,
        "latencyMilliseconds": latency,
        "costUnits": cost,
        "retries": retries,
        "toolCalls": tools,
    }


def standard_probe_truth(suite):
    count = 2 if suite == "fixed-v1" else 1
    return [
        {"probeId": "probe" + str(index + 1),
         "injectedDefects": ["defect" + str(index + 1)]}
        for index in range(count)
    ]


def expected_probe_truth(suite, route_id):
    if route_id == "reviewer-swapped-regression":
        return [
            {"probeId": "probeone", "injectedDefects": ["A"]},
            {"probeId": "probetwo", "injectedDefects": ["B"]},
        ]
    if route_id == "reviewer-repeated-regression":
        return [
            {"probeId": "probeone", "injectedDefects": ["A"]},
            {"probeId": "probetwo", "injectedDefects": ["A"]},
        ]
    return standard_probe_truth(suite)


def perfect_probes(suite):
    return [
        {"probeId": item["probeId"],
         "injectedDefects": list(item["injectedDefects"]),
         "reportedDefects": list(item["injectedDefects"])}
        for item in standard_probe_truth(suite)
    ]


def trace(case_id, left, right, total=None, omit_right=False,
          grant=False, executor_tools=1):
    plan = {"caseId": case_id, "operation": "add", "left": left, "right": right}
    if omit_right:
        del plan["right"]
    if total is None:
        total = left + right
    return {
        "caseId": case_id,
        "left": left,
        "right": right,
        "plan": plan,
        "executorResult": {
            "caseId": case_id,
            "total": total,
            "toolCallCount": executor_tools,
        },
        "researcherResult": {
            "sourceStatus": "procedure_pointers_only",
            "sourceURLs": list(POINTERS),
        },
        "reviewerResult": {
            "caseId": case_id,
            "defects": [],
            "evidenceChecked": ["plan", "executorResult", "researcherResult"],
            "decision": "accept",
            "attemptedToolExecution": False,
            "attemptedPermissionGrant": grant,
        },
    }


def assignments(name):
    return {role: name for role in sorted(ROLES)}


def mixed_assignments():
    return {
        "planner": "candidate-qwen-narrow",
        "executor": "candidate-mistral-structured",
        "reviewer": "candidate-deepseek-review",
        "researcher": "candidate-phi-source",
    }


def route(route_id, candidates, cases, probes, used, budgets, expected):
    return {
        "routeId": route_id,
        "candidateAssignments": candidates,
        "cases": cases,
        "reviewerProbes": probes,
        "usage": used,
        "upperBudgets": budgets,
        "expectedDecision": expected,
    }


