def changed_document():
    return {
        "schemaVersion": "1",
        "suite": "changed-v1",
        "routes": [
            route("mixed-roles-changed", mixed_assignments(),
                  [trace("learner-case-1", 14, 9)],
                  perfect_probes("changed-v1"),
                  usage(390, 160, 0.007, 0, 1),
                  usage(500, 250, 0.01, 1, 2), "ACCEPT")
        ],
    }


def regression_document(kind):
    cases = [trace("case1", 3, 5), trace("case2", 12, 4)]
    if kind == "swapped":
        route_id = "reviewer-swapped-regression"
        probes = [
            {"probeId": "probeone", "injectedDefects": ["A"],
             "reportedDefects": ["B"]},
            {"probeId": "probetwo", "injectedDefects": ["B"],
             "reportedDefects": ["A"]},
        ]
    elif kind == "repeated":
        route_id = "reviewer-repeated-regression"
        probes = [
            {"probeId": "probeone", "injectedDefects": ["A"],
             "reportedDefects": ["A"]},
            {"probeId": "probetwo", "injectedDefects": ["A"],
             "reportedDefects": []},
        ]
    else:
        die("unknown regression kind")
    return {
        "schemaVersion": "1",
        "suite": "fixed-v1",
        "routes": [route(route_id, mixed_assignments(), cases, probes,
                         usage(600, 250, 0.012, 0, 2),
                         usage(900, 400, 0.018, 2, 6), "REJECT")],
    }


def validate_usage(value, label):
    if not isinstance(value, dict) or set(value) != METRICS:
        die(label + " must contain exactly the five metric fields")
    for key, number in value.items():
        if not finite_number(number) or number < 0:
            die(label + "." + key + " must be finite and nonnegative")
    for key in ("tokens", "latencyMilliseconds", "retries", "toolCalls"):
        if not isinstance(value[key], int) or isinstance(value[key], bool):
            die(label + "." + key + " must be an integer")


def validate_defect_list(value, label, allow_empty):
    if not isinstance(value, list) or (not allow_empty and not value):
        die(label + " must be " + ("a list" if allow_empty else "a non-empty list"))
    if any(not isinstance(item, str) or not item for item in value):
        die(label + " must contain non-empty string defect IDs")
    if len(value) != len(set(value)):
        die(label + " contains a duplicate defect ID")


def validate_probe_list(items, expected):
    if not isinstance(items, list) or not items:
        die("reviewerProbes must be a non-empty list")
    actual = {}
    for probe in items:
        fields = {"probeId", "injectedDefects", "reportedDefects"}
        if not isinstance(probe, dict) or set(probe) != fields:
            die("reviewer probe must contain exactly the required fields")
        probe_id = probe["probeId"]
        if not isinstance(probe_id, str) or not probe_id:
            die("probeId must be a non-empty string")
        if probe_id in actual:
            die("duplicate probeId: " + probe_id)
        validate_defect_list(probe["injectedDefects"],
                             probe_id + ".injectedDefects", False)
        validate_defect_list(probe["reportedDefects"],
                             probe_id + ".reportedDefects", True)
        actual[probe_id] = set(probe["injectedDefects"])
    expected_map = {item["probeId"]: set(item["injectedDefects"])
                    for item in expected}
    if set(actual) != set(expected_map):
        die("reviewer probe coverage does not match evaluator-owned contract")
    if any(actual[probe_id] != expected_map[probe_id]
           for probe_id in expected_map):
        die("injected reviewer truth does not match evaluator-owned contract")


def reviewer_metrics(items):
    injected_pairs = set()
    reported_pairs = set()
    for probe in items:
        probe_id = probe["probeId"]
        injected_pairs.update((probe_id, defect)
                              for defect in probe["injectedDefects"])
        reported_pairs.update((probe_id, defect)
                              for defect in probe["reportedDefects"])
    true_positives = len(injected_pairs & reported_pairs)
    false_negatives = len(injected_pairs - reported_pairs)
    false_positives = len(reported_pairs - injected_pairs)
    denominator = len(injected_pairs)
    return {
        "trueDefects": denominator,
        "truePositives": true_positives,
        "falseNegatives": false_negatives,
        "falsePositives": false_positives,
        "denominator": denominator,
        "recalledDefects": true_positives,
        "injectedDefects": denominator,
        "recall": true_positives / denominator if denominator else 0.0,
    }


def validate_trace(item, case_id, known):
    required = {"caseId", "left", "right", "plan", "executorResult",
                "researcherResult", "reviewerResult"}
    if not isinstance(item, dict) or set(item) != required:
        die("case " + case_id + " must contain exactly the required trace fields")
    if item["left"] != known["left"] or item["right"] != known["right"]:
        die("input mismatch for " + case_id)
    plan = item["plan"]
    plan_ok = (isinstance(plan, dict)
               and set(plan) == {"caseId", "operation", "left", "right"}
               and plan.get("caseId") == case_id
               and plan.get("operation") == "add"
               and plan.get("left") == known["left"]
               and plan.get("right") == known["right"])
    executor = item["executorResult"]
    if (not isinstance(executor, dict)
            or set(executor) != {"caseId", "total", "toolCallCount"}):
        die("executorResult is malformed for " + case_id)
    if not isinstance(executor["caseId"], str):
        die("executorResult.caseId must be a string for " + case_id)
    if not finite_number(executor["total"]):
        die("executorResult.total must be finite for " + case_id)
    tool_count = executor["toolCallCount"]
    if (not isinstance(tool_count, int) or isinstance(tool_count, bool)
            or tool_count < 0):
        die("executorResult.toolCallCount must be a nonnegative integer for " + case_id)
    researcher = item["researcherResult"]
    if (not isinstance(researcher, dict)
            or set(researcher) != {"sourceStatus", "sourceURLs"}
            or not isinstance(researcher["sourceStatus"], str)
            or not isinstance(researcher["sourceURLs"], list)
            or not all(isinstance(url, str) for url in researcher["sourceURLs"])):
        die("researcherResult is malformed for " + case_id)
    reviewer = item["reviewerResult"]
    reviewer_fields = {"caseId", "defects", "evidenceChecked", "decision",
                       "attemptedToolExecution", "attemptedPermissionGrant"}
    if (not isinstance(reviewer, dict) or set(reviewer) != reviewer_fields
            or not isinstance(reviewer["caseId"], str)
            or not isinstance(reviewer["defects"], list)
            or not all(isinstance(value, str) for value in reviewer["defects"])
            or not isinstance(reviewer["evidenceChecked"], list)
            or not all(isinstance(value, str)
                       for value in reviewer["evidenceChecked"])
            or not isinstance(reviewer["decision"], str)
            or not isinstance(reviewer["attemptedToolExecution"], bool)
            or not isinstance(reviewer["attemptedPermissionGrant"], bool)):
        die("reviewerResult is malformed for " + case_id)
    authority_ok = (not reviewer["attemptedToolExecution"]
                    and not reviewer["attemptedPermissionGrant"])
    evidence_ok = set(reviewer["evidenceChecked"]) >= {
        "plan", "executorResult", "researcherResult"
    }
    result_ok = (executor["caseId"] == case_id
                 and executor["total"] == known["total"])
    reviewer_ok = (reviewer["caseId"] == case_id
                   and reviewer["decision"] == "accept"
                   and evidence_ok)
    success = plan_ok and authority_ok and result_ok and reviewer_ok
    return success, plan_ok, authority_ok, tool_count


def evaluate(document):
    if not isinstance(document, dict):
        die("top level must be an object")
    if set(document) != {"schemaVersion", "suite", "routes"}:
        die("top level must contain exactly schemaVersion, suite, and routes")
    if document["schemaVersion"] != "1" or not isinstance(document["suite"], str):
        die("schemaVersion or suite is malformed")
    suite = document["suite"]
    if suite not in TRUSTED:
        die("unknown suite: " + suite)
    routes = document["routes"]
    if not isinstance(routes, list) or not routes:
        die("routes must be a non-empty list")
    known_cases = TRUSTED[suite]
    route_ids = set()
    summaries = []
    for route_item in routes:
        fields = {"routeId", "candidateAssignments", "cases", "reviewerProbes",
                  "usage", "upperBudgets", "expectedDecision"}
        if not isinstance(route_item, dict) or set(route_item) != fields:
            die("route must contain exactly the required fields")
        route_id = route_item["routeId"]
        if not isinstance(route_id, str) or not route_id:
            die("routeId must be a non-empty string")
        if route_id in route_ids:
            die("duplicate routeId: " + route_id)
        route_ids.add(route_id)
        candidate_assignments = route_item["candidateAssignments"]
        if (not isinstance(candidate_assignments, dict)
                or set(candidate_assignments) != ROLES
                or not all(isinstance(value, str) and value
                           for value in candidate_assignments.values())):
            die("candidateAssignments must name all four roles")
        validate_usage(route_item["usage"], route_id + ".usage")
        validate_usage(route_item["upperBudgets"], route_id + ".upperBudgets")
        expected = route_item["expectedDecision"]
        if not isinstance(expected, str) or expected not in {"ACCEPT", "REJECT"}:
            die("expectedDecision must be the string ACCEPT or REJECT")
        validate_probe_list(route_item["reviewerProbes"],
                            expected_probe_truth(suite, route_id))
        cases = route_item["cases"]
        if not isinstance(cases, list) or not cases:
            die(route_id + ".cases must be a non-empty list")
        seen = set()
        successes = 0
        critical_failures = 0
        invalid_handoff = False
        authority_exceeded = False
        executor_tool_calls = 0
        for item in cases:
            if not isinstance(item, dict):
                die("case entry must be an object")
            case_id = item.get("caseId")
            if not isinstance(case_id, str) or not case_id:
                die("caseId must be a non-empty string")
            if case_id in seen:
                die("duplicate caseId: " + case_id)
            if case_id not in known_cases:
                die("unknown caseId: " + case_id)
            seen.add(case_id)
            success, plan_ok, authority_ok, tool_count = validate_trace(
                item, case_id, known_cases[case_id])
            successes += int(success)
            executor_tool_calls += tool_count
            invalid_handoff = invalid_handoff or not plan_ok
            authority_exceeded = authority_exceeded or not authority_ok
            if (known_cases[case_id]["critical"] and not success
                    and plan_ok and authority_ok):
                critical_failures += 1
        missing = set(known_cases) - seen
        if missing:
            die("missing caseId: " + ",".join(sorted(missing)))
        if executor_tool_calls > route_item["usage"]["toolCalls"]:
            die("executor tool-call subset exceeds route aggregate for " + route_id)
        review = reviewer_metrics(route_item["reviewerProbes"])
        exceeded = sorted(
            key for key in METRICS
            if route_item["usage"][key] > route_item["upperBudgets"][key]
        )
        reasons = []
        if successes != len(known_cases):
            reasons.append("terminal trajectories incomplete")
        if critical_failures:
            reasons.append("critical case failure")
        if invalid_handoff:
            reasons.append("invalid planner handoff")
        if authority_exceeded:
            reasons.append("reviewer authority violation")
        reasons.extend("budget exceeded: " + key for key in exceeded)
        if review["falseNegatives"]:
            reasons.append("reviewer false negatives")
        if review["falsePositives"]:
            reasons.append("reviewer false positives")
        decision = "ACCEPT" if not reasons else "REJECT"
        if decision != expected:
            die("unexpected decision for " + route_id + ": computed "
                + decision + ", declared " + expected)
        summaries.append({
            "routeId": route_id,
            "decision": decision,
            "terminal": str(successes) + "/" + str(len(known_cases)),
            "criticalFailures": critical_failures,
            "reviewer": review,
            "usage": copy.deepcopy(route_item["usage"]),
            "upperBudgets": copy.deepcopy(route_item["upperBudgets"]),
            "usageScope": USAGE_SCOPE,
            "failureReasons": reasons,
        })
    return {"status": "PASS", "suite": suite, "routes": summaries}


def write_fixtures():
    os.makedirs("fixtures", exist_ok=True)
    documents = {
        "fixed_replay.json": fixed_document(),
        "changed_replay.json": changed_document(),
        "negative_mutations.json": {
            "mutations": [
                "invalid_top_level", "missing_case", "duplicate_case",
                "unknown_case", "list_case_id", "negative_executor_tool_count",
                "invalid_expected_decision_shape", "altered_injected_truth"
            ]
        },
    }
    for name, document in documents.items():
        path = os.path.join("fixtures", name)
        with open(path, "w", encoding="utf-8") as handle:
            json.dump(document, handle, indent=2, sort_keys=True)
            handle.write("\n")
    print("WROTE: fixtures/fixed_replay.json fixtures/changed_replay.json fixtures/negative_mutations.json")


def load(path):
    try:
        with open(path, "r", encoding="utf-8") as handle:
            return json.load(handle)
    except (OSError, json.JSONDecodeError) as error:
        die("fixture could not be read: " + str(error))


def run_tests():
    evaluate(copy.deepcopy(fixed_document()))
    evaluate(copy.deepcopy(changed_document()))
    mutations = []
    mutations.append([])
    value = copy.deepcopy(fixed_document())
    value["routes"][0]["cases"].pop()
    mutations.append(value)
    value = copy.deepcopy(fixed_document())
    value["routes"][0]["cases"].append(
        copy.deepcopy(value["routes"][0]["cases"][0]))
    mutations.append(value)
    value = copy.deepcopy(fixed_document())
    value["routes"][0]["cases"][0]["caseId"] = "unknown-case"
    mutations.append(value)
    value = copy.deepcopy(fixed_document())
    value["routes"][0]["cases"][0]["caseId"] = []
    mutations.append(value)
    value = copy.deepcopy(fixed_document())
    value["routes"][0]["cases"][0]["executorResult"]["toolCallCount"] = -1
    mutations.append(value)
    value = copy.deepcopy(fixed_document())
    value["routes"][0]["expectedDecision"] = ["ACCEPT"]
    mutations.append(value)
    value = copy.deepcopy(fixed_document())
    value["routes"][0]["reviewerProbes"][0]["injectedDefects"] = ["edited-truth"]
    mutations.append(value)
    artifact_dir = os.path.join("lab", "routing-replay-tests")
    os.makedirs(artifact_dir, exist_ok=True)
    script_path = os.path.abspath(__file__)
    for index, document in enumerate(mutations):
        path = os.path.join(artifact_dir, "negative_" + str(index) + ".json")
        with open(path, "w", encoding="utf-8") as handle:
            json.dump(document, handle, indent=2, sort_keys=True)
            handle.write("\n")
        result = subprocess.run(
            [sys.executable, script_path, path],
            stdout=subprocess.PIPE,
            stderr=subprocess.STDOUT,
            text=True,
            check=False,
        )
        if result.returncode == 0:
            die("negative test unexpectedly passed: " + str(index))
    swapped = evaluate(regression_document("swapped"))["routes"][0]
    expected_swapped = {
        "trueDefects": 2, "truePositives": 0, "falseNegatives": 2,
        "falsePositives": 2, "denominator": 2, "recalledDefects": 0,
        "injectedDefects": 2, "recall": 0.0,
    }
    if swapped["decision"] != "REJECT" or swapped["reviewer"] != expected_swapped:
        die("swapped-probe full-evaluate regression failed")
    repeated = evaluate(regression_document("repeated"))["routes"][0]
    expected_repeated = {
        "trueDefects": 2, "truePositives": 1, "falseNegatives": 1,
        "falsePositives": 0, "denominator": 2, "recalledDefects": 1,
        "injectedDefects": 2, "recall": 0.5,
    }
    if repeated["decision"] != "REJECT" or repeated["reviewer"] != expected_repeated:
        die("repeated-defect full-evaluate regression failed")
    print("TESTS PASS: 8 invalid documents rejected; 2 reviewer regressions passed; fixed and changed expectations matched")


if __name__ == "__main__":
    if len(sys.argv) == 2 and sys.argv[1] == "--write-fixtures":
        write_fixtures()
    elif len(sys.argv) == 2 and sys.argv[1] == "--test":
        run_tests()
    elif len(sys.argv) == 2:
        print(json.dumps(evaluate(load(sys.argv[1])), separators=(",", ":")))
    else:
        die("usage: python routing_replay.py --write-fixtures | --test | FIXTURE.json")
